      'upd', 'update public.inventory_recon set rule_id = rule_id where line_key = ''T|setup'''),
    'variance_month', jsonb_build_object('w', '["admin","finance","cost_accounting"]'::jsonb, 'r', '["admin","finance","cost_accounting","management","ppic","purchasing","sales"]'::jsonb,
